promptFull:
// ============================================================
// スケジュール抽出ツール（最終版）
// 機能：①キャパチェック ②申請期限チェック ③イレギュラー警告
// ④顧客NG日 ⑤着工日表示 ⑥案A（平日）/ 案B（土日）ブロック表示
// ============================================================

function onOpen() {
 const ui = SpreadsheetApp.getUi();
 ui.createMenu('📅 スケジュール抽出')
 .addItem('実行する', 'findFullSchedule')
 .addToUi();
}

function findFullSchedule() {
 const ss = SpreadsheetApp.getActiveSpreadsheet();
 const mainSheet = ss.getSheetByName('メイン');

 const planName = mainSheet.getRange('B1').getValue();
 const variableMember = mainSheet.getRange('B2').getValue();
 const firstStartDateVal = mainSheet.getRange('B3').getValue();
 const applicationFlag = mainSheet.getRange('B4').getValue();
 const applicationMonthVal = mainSheet.getRange('B5').getValue();
 const applicationMeetingName = mainSheet.getRange('B6').getValue();
 const constructionDateVal = mainSheet.getRange('B7').getValue();
 const customerNgDates = loadCustomerNgDates(mainSheet);

 if (!planName) { Browser.msgBox('B1セルでプランを選択してください。'); return; }
 if (!firstStartDateVal) { Browser.msgBox('B3セルに初回検索開始日を入力してください。'); return; }

 let baseDate = new Date(firstStartDateVal);
 baseDate.setHours(0, 0, 0, 0);

 let constructionDate = null;
 if (constructionDateVal) {
 constructionDate = new Date(constructionDateVal);
 constructionDate.setHours(0, 0, 0, 0);
 }

 let settingSheetName = planName === 'デザイン制作ツール' ? 'デザイン制作ツール設定' : planName === '自社商品' ? '自社商品設定' : null;
 if (!settingSheetName) { Browser.msgBox('プラン名（' + planName + '）が正しくありません。'); return; }

 const settingSheet = ss.getSheetByName(settingSheetName);
 if (!settingSheet) { Browser.msgBox('「' + settingSheetName + '」シートが見つかりません。'); return; }

 const capacitySheet = ss.getSheetByName('キャパ設定');
 if (!capacitySheet) { Browser.msgBox('「キャパ設定」シートが見つかりません。'); return; }
 const capacityRules = loadCapacityRules(capacitySheet, planName);

 const lastRow = settingSheet.getLastRow();
 if (lastRow < 2) return;
 const meetingData = settingSheet.getRange(2, 1, lastRow - 1, 4).getValues();

 let applicationDeadline = null;
 if (applicationFlag === 'あり' && applicationMonthVal) {
 applicationDeadline = parseApplicationMonth(applicationMonthVal);
 }

 const bufferMin = 60;
 const daysToSearch = 90;

 // ============================================================
 // 共通：1件の打合せの空き枠を探す
 // ============================================================
 function findSlot(meetingName, durationMin, members, searchStartDay, currentBase, intervalDays, meetingIndex, isApplicationMeeting, allMemberEvents, usageTracker, mode) {
 for (let d = 0; d < daysToSearch; d++) {
 let checkDate = new Date(searchStartDay);
 checkDate.setDate(searchStartDay.getDate() + d);
 let dayOfWeek = checkDate.getDay();

 if (mode === 'weekend' && dayOfWeek !== 0 && dayOfWeek !== 6) continue;
 if (mode === 'weekday' && (dayOfWeek === 0 || dayOfWeek === 6)) continue;

 if (isApplicationMeeting && applicationDeadline && checkDate >= applicationDeadline) break;
 if (isCustomerNgDate(customerNgDates, checkDate)) continue;
 if (!checkCapacity(capacityRules, meetingName, members, checkDate, usageTracker, planName)) continue;

 let noonStart = new Date(checkDate); noonStart.setHours(12, 0, 0, 0);
 let noonEnd = new Date(checkDate); noonEnd.setHours(13, 0, 0, 0);

 for (let hour = 9; hour <= 16; hour++) {
 for (let min = 0; min < 60; min += 30) {
 let meetingStart = new Date(checkDate);
 meetingStart.setHours(hour, min, 0, 0);
 let meetingEnd = new Date(meetingStart);
 meetingEnd.setMinutes(meetingStart.getMinutes() + Number(durationMin));

 if (Number(durationMin) === 240) {
 if (!(hour === 9 && min === 0) && !(hour === 14 && min === 0)) continue;
 } else {
 if (meetingStart < noonEnd && meetingEnd > noonStart) continue;
 }

 let checkStart = new Date(meetingStart);
 checkStart.setMinutes(meetingStart.getMinutes() - bufferMin);
 let checkEnd = new Date(meetingEnd);
 checkEnd.setMinutes(meetingEnd.getMinutes() + bufferMin);

 let isAvailable = true;
 for (let m = 0; m < allMemberEvents.length; m++) {
 for (let e = 0; e < allMemberEvents[m].length; e++) {
 let evStart = allMemberEvents[m][e].getStartTime();
 let evEnd = allMemberEvents[m][e].getEndTime();
 if (evStart < checkEnd && evEnd > checkStart) { isAvailable = false; break; }
 }
 if (!isAvailable) break;
 }

 if (isAvailable) {
 let dayStr = ['(日)', '(月)', '(火)', '(水)', '(木)', '(金)', '(土)'][dayOfWeek];
 let remarks = '';
 let actualInterval = Math.round((meetingStart - currentBase) / (1000 * 60 * 60 * 24));
 if (meetingIndex > 0 && actualInterval < Number(intervalDays)) {
 remarks = '⚠️ イレギュラー：間隔' + actualInterval + '日（規定' + intervalDays + '日、要相談）';
 }
 if (isApplicationMeeting && applicationDeadline) {
 let daysLeft = Math.round((applicationDeadline - meetingStart) / (1000 * 60 * 60 * 24));
 remarks += (remarks ? ' / ' : '') + '📋 申請まで' + daysLeft + '日';
 }
 if (planName === '自社商品' && meetingName === '詳細設計') {
 let prevDay = new Date(checkDate); prevDay.setDate(checkDate.getDate() - 1);
 let nextDay = new Date(checkDate); nextDay.setDate(checkDate.getDate() + 1);
 if (isConsecutiveDetailDesign(usageTracker, prevDay, nextDay)) {
 remarks += (remarks ? ' / ' : '') + '💬 詳細設計2日連続：要相談';
 }
 }
 return {
 found: true,
 date: new Date(meetingStart),
 dateStr: Utilities.formatDate(meetingStart, 'JST', 'yyyy/MM/dd') + ' ' + dayStr,
 startStr: Utilities.formatDate(meetingStart, 'JST', 'HH:mm'),
 endStr: Utilities.formatDate(meetingEnd, 'JST', 'HH:mm'),
 remarks
 };
 }
 }
 }
 }
 return { found: false };
 }

 // ============================================================
 // スケジュールを組む（splitIndex以降をmodeで組む）
 // ============================================================
 function buildSchedule(mode, startIndex, startBaseDate) {
 let rows = [];
 let currentBase = new Date(startBaseDate);
 let usageTracker = {};
 let yonshaDate = null;

 for (let i = startIndex; i < meetingData.length; i++) {
 let meetingName = meetingData[i][0];
 let durationMin = meetingData[i][1];
 let membersRaw = meetingData[i][2];
 let intervalDays = meetingData[i][3];
 if (!meetingName || !durationMin || !membersRaw) continue;

 if (variableMember) {
 membersRaw = String(membersRaw).replace('[変動担当者]', variableMember);
 } else {
 membersRaw = String(membersRaw).replace(/,?\[変動担当者\]/g, '').replace(/\[変動担当者\],?/g, '');
 }
 let members = String(membersRaw).split(',').map(m => m.trim()).filter(m => m.length > 0);

 let searchStartDay = new Date(currentBase);
 searchStartDay.setDate(searchStartDay.getDate() + Number(intervalDays));
 searchStartDay.setHours(0, 0, 0, 0);

 let searchEndDay = new Date(searchStartDay);
 searchEndDay.setDate(searchEndDay.getDate() + daysToSearch);
 searchEndDay.setHours(23, 59, 59, 999);

 let isApplicationMeeting = (applicationDeadline && meetingName === applicationMeetingName);
 let allMemberEvents = [];
 for (let j = 0; j < members.length; j++) {
 let cal = CalendarApp.getCalendarById(members[j]);
 if (cal) allMemberEvents.push(cal.getEvents(searchStartDay, searchEndDay));
 }

 let result = findSlot(meetingName, durationMin, members, searchStartDay, currentBase, intervalDays, i, isApplicationMeeting, allMemberEvents, usageTracker, mode);

 if (result.found) {
 if (meetingName === '4者引継ぎ' || meetingName === '4者') yonshaDate = new Date(result.date);
 rows.push({ meetingName, dateStr: result.dateStr, startStr: result.startStr, endStr: result.endStr, members: members.join(', '), remarks: result.remarks, found: true });
 recordUsage(usageTracker, meetingName, members, result.date, capacityRules);
 currentBase = new Date(result.date);
 } else {
 let msg = (isApplicationMeeting && applicationDeadline) ? '🚨 申請期限までに空きなし' : '※空きが見つかりませんでした';
 let rmk = (isApplicationMeeting && applicationDeadline) ? '要緊急対応' : '';
 rows.push({ meetingName, dateStr: msg, startStr: '', endStr: '', members: members.join(', '), remarks: rmk, found: false });
 for (let k = i + 1; k < meetingData.length; k++) {
 if (meetingData[k][0]) rows.push({ meetingName: meetingData[k][0], dateStr: '（前の打合せが未確定のためスキップ）', startStr: '', endStr: '', members: '', remarks: '', found: false });
 }
 break;
 }
 }
 return { rows, yonshaDate };
 }

 // ============================================================
 // メイン処理：土日で順番に試し、空きなし発生時点でA/B分岐
 // ============================================================
 let confirmedRows = [];
 let splitIndex = -1;
 let splitBaseDate = new Date(baseDate);
 let currentBase = new Date(baseDate);
 let usageTrackerPre = {};

 for (let i = 0; i < meetingData.length; i++) {
 let meetingName = meetingData[i][0];
 let durationMin = meetingData[i][1];
 let membersRaw = meetingData[i][2];
 let intervalDays = meetingData[i][3];
 if (!meetingName || !durationMin || !membersRaw) continue;

 if (variableMember) {
 membersRaw = String(membersRaw).replace('[変動担当者]', variableMember);
 } else {
 membersRaw = String(membersRaw).replace(/,?\[変動担当者\]/g, '').replace(/\[変動担当者\],?/g, '');
 }
 let members = String(membersRaw).split(',').map(m => m.trim()).filter(m => m.length > 0);

 let searchStartDay = new Date(currentBase);
 searchStartDay.setDate(searchStartDay.getDate() + Number(intervalDays));
 searchStartDay.setHours(0, 0, 0, 0);

 let searchEndDay = new Date(searchStartDay);
 searchEndDay.setDate(searchEndDay.getDate() + daysToSearch);
 searchEndDay.setHours(23, 59, 59, 999);

 let isApplicationMeeting = (applicationDeadline && meetingName === applicationMeetingName);
 let allMemberEvents = [];
 for (let j = 0; j < members.length; j++) {
 let cal = CalendarApp.getCalendarById(members[j]);
 if (cal) allMemberEvents.push(cal.getEvents(searchStartDay, searchEndDay));
 }

 let result = findSlot(meetingName, durationMin, members, searchStartDay, currentBase, intervalDays, i, isApplicationMeeting, allMemberEvents, usageTrackerPre, 'weekend');

 if (result.found) {
 if (meetingName === '4者引継ぎ' || meetingName === '4者') {
 // 4者が確定ならそのまま確定済みに入れる
 }
 confirmedRows.push({ meetingName, dateStr: result.dateStr, startStr: result.startStr, endStr: result.endStr, members: members.join(', '), remarks: result.remarks, found: true });
 recordUsage(usageTrackerPre, meetingName, members, result.date, capacityRules);
 currentBase = new Date(result.date);
 } else {
 splitIndex = i;
 splitBaseDate = new Date(currentBase);
 break;
 }
 }

 // ============================================================
 // 出力
 // ============================================================
 const resultSheet = ss.getSheetByName('空き時間');
 resultSheet.clear();

 resultSheet.appendRow(['【 ' + planName + ' 】スケジュール案']);
 if (constructionDate) {
 let cd = ['(日)', '(月)', '(火)', '(水)', '(木)', '(金)', '(土)'][constructionDate.getDay()];
 resultSheet.appendRow(['着工日', Utilities.formatDate(constructionDate, 'JST', 'yyyy/MM/dd') + ' ' + cd, '', '', '', '']);
 }
 resultSheet.appendRow(['']);

 function writeHeader(label) {
 resultSheet.appendRow(['━━━ ' + label + ' ━━━', '', '', '', '', '']);
 resultSheet.appendRow(['打合せ名', '日付', '開始時刻', '終了時刻', '参加者', '備考']);
 }

 function writeRows(rows) {
 for (let r = 0; r < rows.length; r++) {
 let row = rows[r];
 resultSheet.appendRow([row.meetingName, row.dateStr, row.startStr, row.endStr, row.members, row.remarks]);
 }
 }

 function writeYonshaCheck(yonshaDate) {
 if (constructionDate && yonshaDate) {
 let gapDays = Math.round((constructionDate - yonshaDate) / (1000 * 60 * 60 * 24));
 let msg = gapDays < 14 ? '🚨 2週間未満：要緊急対応' : gapDays < 30 ? '⚠️ 1ヶ月未満：イレギュラー（要相談）' : '✅ 問題なし';
 resultSheet.appendRow(['【着工まで確認】', '4者引継ぎ→着工：' + gapDays + '日', '', '', '', msg]);
 }
 }

 if (splitIndex === -1) {
 // 空きなし発生なし → 通常出力
 writeHeader('確定スケジュール（土日）');
 writeRows(confirmedRows);
 let lastYonsha = null;
 for (let r = confirmedRows.length - 1; r >= 0; r--) {
 if (confirmedRows[r].meetingName === '4者引継ぎ' || confirmedRows[r].meetingName === '4者') {
 lastYonsha = new Date(confirmedRows[r].dateStr.substring(0, 10));
 break;
 }
 }
 writeYonshaCheck(lastYonsha);
 } else {
 // 確定済みブロック
 if (confirmedRows.length > 0) {
 writeHeader('確定済み（' + meetingData[splitIndex][0] + 'で土日の空きなし）');
 writeRows(confirmedRows);
 resultSheet.appendRow(['']);
 }

 // 案A：平日で組む
 let resultA = buildSchedule('weekday', splitIndex, splitBaseDate);
 writeHeader('案A：平日で組んだ場合');
 writeRows(resultA.rows);
 writeYonshaCheck(resultA.yonshaDate);
 resultSheet.appendRow(['']);

 // 案B：土日で組む（間隔があいてもOK）
 let resultB = buildSchedule('weekend', splitIndex, splitBaseDate);
 writeHeader('案B：土日で組んだ場合（間隔あき）');
 writeRows(resultB.rows);
 writeYonshaCheck(resultB.yonshaDate);
 }

 Browser.msgBox('スケジュール抽出が完了しました。「空き時間」シートをご確認ください。\n\n⚠️マークがある行はイレギュラーです。関係者への相談をお忘れなく。');
}

// ============================================================
// 申請月パース（「9月」「2026/09」「2026/9/1」など対応）
// ============================================================
function parseApplicationMonth(val) {
 if (!val) return null;
 if (val instanceof Date && !isNaN(val.getTime())) return new Date(val.getFullYear(), val.getMonth(), 1);
 let str = String(val).trim();
 let mMatch = str.match(/^(\d{1,2})月$/);
 if (mMatch) { let now = new Date(); return new Date(now.getFullYear(), parseInt(mMatch[1]) - 1, 1); }
 let ymMatch = str.match(/^(\d{4})[\/\-](\d{1,2})$/);
 if (ymMatch) return new Date(parseInt(ymMatch[1]), parseInt(ymMatch[2]) - 1, 1);
 let d = new Date(str);
 if (!isNaN(d.getTime())) return new Date(d.getFullYear(), d.getMonth(), 1);
 return null;
}

// ============================================================
// キャパ設定シートを読み込む
// ============================================================
function loadCapacityRules(capacitySheet, planName) {
 const lastRow = capacitySheet.getLastRow();
 if (lastRow < 2) return [];
 const data = capacitySheet.getRange(2, 1, lastRow - 1, 6).getValues();
 let rules = [];
 for (let i = 0; i < data.length; i++) {
 rules.push({
 staffName: data[i][0],
 email: String(data[i][1]).trim(),
 targetMeetings: String(data[i][2]).split('、').map(m => m.trim()),
 monthlyMax: data[i][3] ? Number(data[i][3]) : null,
 sameWeekNG: String(data[i][4]).includes('NG'),
 isWarningOnly: (planName === '自社商品' && String(data[i][5]).includes('要相談'))
 });
 }
 return rules;
}

// ============================================================
// キャパチェック本体
// ============================================================
function checkCapacity(capacityRules, meetingName, members, checkDate, usageTracker, planName) {
 let monthKey = checkDate.getFullYear() + '-' + String(checkDate.getMonth() + 1).padStart(2, '0');
 let weekKey = getWeekKey(checkDate);
 for (let r = 0; r < capacityRules.length; r++) {
 let rule = capacityRules[r];
 if (!rule.targetMeetings.some(t => meetingName.includes(t) || t.includes(meetingName))) continue;
 if (!members.some(m => m === rule.email)) continue;
 let tk = rule.email + '_' + meetingName;
 if (rule.monthlyMax && (usageTracker[tk + '_month_' + monthKey] || 0) >= rule.monthlyMax) return false;
 if (rule.sameWeekNG && !rule.isWarningOnly && (usageTracker[tk + '_week_' + weekKey] || 0) >= 1) return false;
 }
 return true;
}

// ============================================================
// 使用実績を記録する
// ============================================================
function recordUsage(usageTracker, meetingName, members, meetingStart, capacityRules) {
 let monthKey = meetingStart.getFullYear() + '-' + String(meetingStart.getMonth() + 1).padStart(2, '0');
 let weekKey = getWeekKey(meetingStart);
 for (let r = 0; r < capacityRules.length; r++) {
 let rule = capacityRules[r];
 if (!rule.targetMeetings.some(t => meetingName.includes(t) || t.includes(meetingName))) continue;
 if (!members.some(m => m === rule.email)) continue;
 let tk = rule.email + '_' + meetingName;
 usageTracker[tk + '_month_' + monthKey] = (usageTracker[tk + '_month_' + monthKey] || 0) + 1;
 usageTracker[tk + '_week_' + weekKey] = (usageTracker[tk + '_week_' + weekKey] || 0) + 1;
 }
}

// ============================================================
// 週キーを生成する（月曜日基準）
// ============================================================
function getWeekKey(date) {
 let d = new Date(date);
 let day = d.getDay();
 d.setDate(d.getDate() - day + (day === 0 ? -6 : 1));
 return Utilities.formatDate(d, 'JST', 'yyyy-MM-dd');
}

// ============================================================
// 自社商品詳細設計の2日連続チェック
// ============================================================
function isConsecutiveDetailDesign(usageTracker, prevDay, nextDay) {
 let prevKey = 'detailDesign_' + Utilities.formatDate(prevDay, 'JST', 'yyyy-MM-dd');
 let nextKey = 'detailDesign_' + Utilities.formatDate(nextDay, 'JST', 'yyyy-MM-dd');
 return (usageTracker[prevKey] || usageTracker[nextKey]);
}

// ============================================================
// 顧客NG日をメインシートから読み込む（B8以降）
// ============================================================
function loadCustomerNgDates(mainSheet) {
 let ngDates = [];
 const lastRow = mainSheet.getLastRow();
 if (lastRow < 8) return ngDates;
 const values = mainSheet.getRange(8, 2, lastRow - 7, 1).getValues();
 for (let i = 0; i < values.length; i++) {
 let val = values[i][0];
 if (!val) continue;
 let d = new Date(val);
 if (!isNaN(d.getTime())) { d.setHours(0, 0, 0, 0); ngDates.push(d); }
 }
 return ngDates;
}

// ============================================================
// 指定日が顧客NG日かどうかを判定する
// ============================================================
function isCustomerNgDate(ngDates, checkDate) {
 let check = new Date(checkDate);
 check.setHours(0, 0, 0, 0);
 for (let i = 0; i < ngDates.length; i++) {
 if (ngDates[i].getTime() === check.getTime()) return true;
 }
 return false;
}

