/**
 * 「点検代行サービス検査日程一覧」シートのD〜L列をGoogleカレンダー(メインカレンダー)に
 * 自動反映するスクリプト。
 *
 * 使い方:
 * 1. スプレッドシートのメニュー [拡張機能] > [Apps Script] を開く
 * 2. デフォルトの Code.gs の中身をこのファイルの内容に置き換えて保存
 * 3. このスクリプトファイルの onEdit という名前のトリガーは
 * シンプルトリガーとして自動的に動作します(追加設定不要)。
 * ※ シンプルトリガーはカレンダーへのアクセス権限の制約上、
 * 初回のみ [トリガー] メニューからインストーラブルトリガーとして
 * 手動セットアップする必要があります(下記セットアップ手順参照)。
 *
 * 【セットアップ手順(初回のみ)】
 * 1. Apps Scriptエディタ左メニューの「トリガー」(時計アイコン)を開く
 * 2. [トリガーを追加] をクリック
 * 3. 実行する関数: onEditInstallable
 * イベントのソース: スプレッドシートから
 * イベントの種類: 編集時
 * を選択して保存(その際カレンダーへのアクセス許可を求められるので許可する)
 *
 * 列の対応:
 * D列: 着工日 / E列: 上棟日 / F列: 配筋検査 / G列: 土台検査
 * H列: ルーフィング検査 / I列: 金物検査 / J列: 防水検査
 * K列: 竣工検査 / L列: お引渡し日
 *
 * 重複登録防止のため、登録済みのカレンダーイベントIDをシートの
 * N列〜V列(D〜L列にそれぞれ対応)に自動で書き込みます。
 * このID列は手動で編集しないでください。
 */

const TARGET_SHEET_NAME = '点検代行サービス検査日程一覧';
const NAME_COL = 1; // A列: 現場名（顧客情報）
const DATE_COL_START = 4; // D列
const DATE_COL_END = 12; // L列
const ID_COL_OFFSET = 10; // D列(4) + 10 = N列(14) にイベントIDを保存
const HEADER_ROW = 1;

const COLUMN_ITEM_NAMES = {
 4: '着工日',
 5: '上棟日',
 6: '配筋検査',
 7: '土台検査',
 8: 'ルーフィング検査',
 9: '金物検査',
 10: '防水検査',
 11: '竣工検査',
 12: 'お引渡し日'
};

/**
 * インストーラブルトリガー用のエントリポイント。
 * トリガー設定画面で「onEditInstallable」を選択してください。
 */
function onEditInstallable(e) {
 try {
 handleEdit(e);
 } catch (err) {
 Logger.log('エラー: ' + err.message);
 }
}

function handleEdit(e) {
 const sheet = e.range.getSheet();
 if (sheet.getName() !== TARGET_SHEET_NAME) return;

 const range = e.range;
 const startRow = range.getRow();
 const numRows = range.getNumRows();
 const startCol = range.getColumn();
 const numCols = range.getNumColumns();

 // ヘッダー行の編集は無視
 if (startRow <= HEADER_ROW && startRow + numRows - 1 <= HEADER_ROW) return;

 // 編集範囲がD〜L列と重なっていなければ何もしない
 const editEndCol = startCol + numCols - 1;
 if (editEndCol < DATE_COL_START || startCol > DATE_COL_END) return;

 const calendar = CalendarApp.getDefaultCalendar();

 for (let r = startRow; r < startRow + numRows; r++) {
 if (r <= HEADER_ROW) continue;

 const siteName = sheet.getRange(r, NAME_COL).getValue();
 if (!siteName) continue; // 現場名が空の行はスキップ

 for (let c = Math.max(startCol, DATE_COL_START); c <= Math.min(editEndCol, DATE_COL_END); c++) {
 syncCell(sheet, calendar, r, c, siteName);
 }
 }
}

/**
 * 指定セル1件分を同期する(作成・更新・削除)。
 */
function syncCell(sheet, calendar, row, col, siteName) {
 const dateValue = sheet.getRange(row, col).getValue();
 const idCol = col + ID_COL_OFFSET;
 const idCell = sheet.getRange(row, idCol);
 const existingId = idCell.getValue();
 const itemName = COLUMN_ITEM_NAMES[col];
 const title = siteName + ' ' + itemName;

 // 日付が消された場合: 既存イベントがあれば削除
 if (!dateValue) {
 if (existingId) {
