// 日付列 → {time: 時間列, item: 項目名, idCol: イベントID保存列}
const COLUMN_MAP = {
 4: { time: 5, item: '着工日', idCol: 23 }, // D,E -> W
 6: { time: 7, item: '上棟日', idCol: 24 }, // F,G -> X
 8: { time: 9, item: '配筋検査', idCol: 25 }, // H,I -> Y
 10: { time: 11, item: '土台検査', idCol: 26 }, // J,K -> Z
 12: { time: 13, item: 'ルーフィング検査', idCol: 27 }, // L,M -> AA
 14: { time: 15, item: '金物検査', idCol: 28 }, // N,O -> AB
 16: { time: 17, item: '防水検査', idCol: 29 }, // P,Q -> AC
 18: { time: 19, item: '竣工検査', idCol: 30 }, // R,S -> AD
 20: { time: 21, item: 'お引渡し日', idCol: 31 } // T,U -> AE
};

const DATE_COLS = Object.keys(COLUMN_MAP).map(Number); // [4,6,8,...,20]
const ALL_RELEVANT_COLS = [];
DATE_COLS.forEach(dc => {
 ALL_RELEVANT_COLS.push(dc, COLUMN_MAP[dc].time);
});

function onEditInstallable(e) {
 try {
 handleEdit(e);
 } catch (err) {
 Logger.log('エラー: ' + err.message);
 }
}

function handleEdit(e) {
 const sheet = e.range.getSheet();
 if (sheet.getName() !== TARGET_SHEET_NAME) return;

 const range = e.range;
 const startRow = range.getRow();
 const numRows = range.getNumRows();
 const startCol = range.getColumn();
 const numCols = range.getNumColumns();
 const editEndCol = startCol + numCols - 1;

 // 編集範囲が日付・時間列のどれとも重なっていなければ何もしない
 const minRelevant = Math.min.apply(null, ALL_RELEVANT_COLS);
 const maxRelevant = Math.max.apply(null, ALL_RELEVANT_COLS);
 if (editEndCol < minRelevant || startCol > maxRelevant) return;

 const calendar = CalendarApp.getDefaultCalendar();

 for (let r = startRow; r < startRow + numRows; r++) {
 if (r <= HEADER_ROW) continue;
 const siteName = sheet.getRange(r, NAME_COL).getValue();
 if (!siteName) continue;

 DATE_COLS.forEach(dateCol => {
 const timeCol = COLUMN_MAP[dateCol].time;
 // 編集範囲が日付列か時間列のどちらかにかかっていれば同期
 if ((dateCol >= startCol && dateCol <= editEndCol) ||
 (timeCol >= startCol && timeCol <= editEndCol)) {
 syncCell(sheet, calendar, r, dateCol, siteName);
 }
 });
 }
}

/**
 * 指定行・指定の日付列1件分を同期する(時間列も合わせて参照)。
 */
function syncCell(sheet, calendar, row, dateCol, siteName) {
 const cfg = COLUMN_MAP[dateCol];
 const dateValue = sheet.getRange(row, dateCol).getValue();
 const timeValue = sheet.getRange(row, cfg.time).getValue();
 const idCell = sheet.getRange(row, cfg.idCol);
 const existingId = idCell.getValue();
 const title = siteName + ' ' + cfg.item;

 if (!dateValue) {
 if (existingId) {
 deleteEventSafely(calendar, existingId);
 idCell.clearContent();
 }
 return;
 }

 const baseDate = (dateValue instanceof Date) ? dateValue : new Date(dateValue);
 if (isNaN(baseDate.getTime())) return;

 const timeRange = parseTimeValue(timeValue);

 if (existingId) {
 const event = getEventSafely(calendar, existingId);
 if (event) {
 deleteEventSafely(calendar, existingId); // 終日⇄時間指定の切替に対応するため作り直す
 }
 }

 let newEvent;
 if (timeRange) {
 const start = new Date(baseDate.getFullYear(), baseDate.getMonth(), baseDate.getDate(), timeRange.start.hour, timeRange.start.minute);
 let end;
 if (timeRange.end) {
 end = new Date(baseDate.getFullYear(), baseDate.getMonth(), baseDate.getDate(), timeRange.end.hour, timeRange.end.minute);
 // 終了時刻が開始より前(日またぎ入力ミス等)の場合はデフォルト長さにフォールバック
 if (end.getTime() <= start.getTime()) {
 end = new Date(start.getTime() + DEFAULT_DURATION_MIN * 60 * 1000);
 }
 } else {
 end = new Date(start.getTime() + DEFAULT_DURATION_MIN * 60 * 1000);
 }
 newEvent = calendar.createEvent(title, start, end);
 } else {
 newEvent = calendar.createAllDayEvent(title, baseDate);
 }
 idCell.setValue(newEvent.getId());
}

/**
 * 時間列の値を {start: {hour, minute}, end: {hour, minute}|null} に変換する。
 * 対応フォーマット:
 * - "14:00" → 開始のみ(終了はデフォルト長さ)
 * - "14:00-16:00" / "14:00〜16:00" / "14:00から16:00" → 開始・終了
 * - 時刻のDateオブジェクト、シリアル値(日の端数)も単一時刻として対応
 */
function parseTimeValue(value) {
 if (!value && value !== 0) return null;

 // 範囲指定(文字列のみ対象。区切り文字: - 〜 ～ から)
 if (typeof value === 'string') {
 const rangeMatch = value.match(/(\d{1,2}):(\d{2})\s*(?:-|〜|～|から)\s*(\d{1,2}):(\d{2})/);
 if (rangeMatch) {
 return {
 start: { hour: parseInt(rangeMatch[1], 10), minute: parseInt(rangeMatch[2], 10) },
 end: { hour: parseInt(rangeMatch[3], 10), minute: parseInt(rangeMatch[4], 10) }
 };
 }
 const singleMatch = value.match(/(\d{1,2}):(\d{2})/);
 if (singleMatch) {
 return {
 start: { hour: parseInt(singleMatch[1], 10), minute: parseInt(singleMatch[2], 10) },
 end: null
 };
 }
 return null;
 }

 if (value instanceof Date) {
 return { start: { hour: value.getHours(), minute: value.getMinutes() }, end: null };
 }

 // シリアル値(日の端数)として入っている場合
 if (typeof value === 'number') {
 const totalMinutes = Math.round(value * 24 * 60);
 return {
 start: { hour: Math.floor(totalMinutes / 60) % 24, minute: totalMinutes % 60 },
 end: null
 };
 }

 return null;
}

