 } catch (err) {
 return null;
 }
}

function deleteEventSafely(calendar, eventId) {
 const event = getEventSafely(calendar, eventId);
 if (event) {
 try {
 event.deleteEvent();
 } catch (err) {
 // 既に削除済みの場合は無視
 }
 }
}

