/* =========================================================
 * Chatwork 5日前リマインド通知
 * =========================================================
 *
 * 【事前設定(初回のみ)】
 * Apps Scriptエディタの左メニュー「プロジェクトの設定」(歯車アイコン)を開き、
 * 「スクリプト プロパティ」に以下の2つを追加してください。
 * {チャットツール認証情報} : Chatworkの認証情報
 * {チャットルームID} : 通知先のルームID
 *
 * 【トリガー設定(初回のみ)】
 * 左メニューの「トリガー」(時計アイコン) > [トリガーを追加]
 * 実行する関数: notifyUpcoming5Days
 * イベントのソース: 時間主導型
 * 時間ベースのトリガーのタイプ: 日タイマー
 * 時刻: 午前8時〜9時(任意の時間帯に変更可)
 */

const CHATWORK_LEAD_DAYS = 5;

/**
 * 毎日1回実行: 今日から5日後が該当する日程をChatworkへ通知する。
 */
function notifyUpcoming5Days() {
 const sheet = SpreadsheetApp.getActiveSpreadsheet().getSheetByName(TARGET_SHEET_NAME);
 if (!sheet) {
 throw new Error('シート「' + TARGET_SHEET_NAME + '」が見つかりません');
 }

 const today = new Date();
 const targetDate = new Date(today.getFullYear(), today.getMonth(), today.getDate() + CHATWORK_LEAD_DAYS);
 const targetDateStr = formatDateYmd_(targetDate);

 const lastRow = sheet.getLastRow();
 const messages = [];

 for (let r = HEADER_ROW + 1; r <= lastRow; r++) {
 const siteName = sheet.getRange(r, NAME_COL).getValue();
 if (!siteName) continue;

 DATE_COLS.forEach(dateCol => {
 const cfg = COLUMN_MAP[dateCol];
 const dateValue = sheet.getRange(r, dateCol).getValue();
 if (!dateValue) return;

 const d = (dateValue instanceof Date) ? dateValue : new Date(dateValue);
 if (isNaN(d.getTime())) return;
 if (formatDateYmd_(d) !== targetDateStr) return;

 const timeValue = sheet.getRange(r, cfg.time).getValue();
 const timeRange = parseTimeValue(timeValue);
 let timeLabel = '';
 if (timeRange) {
 timeLabel = ' ' + pad2_(timeRange.start.hour) + ':' + pad2_(timeRange.start.minute);
 if (timeRange.end) {
 timeLabel += '〜' + pad2_(timeRange.end.hour) + ':' + pad2_(timeRange.end.minute);
 }
 }

 messages.push('・' + siteName + ' ' + cfg.item + '(' + targetDateStr + timeLabel + ')');
 });
 }

 if (messages.length === 0) return; // 該当なしの日は通知しない

 const body = '[info][title]5日後の検査・工程予定リマインド(' + targetDateStr + ')[/title]'
 + messages.join('\n') + '[/info]';
 sendChatworkMessage_(body);
}

/**
 * Chatworkへメッセージを送信する。
 */
function sendChatworkMessage_(message) {
 const props = PropertiesService.getScriptProperties();
 const 認証情報
 const roomId = props.getProperty('{チャットルームID}');

 if (!token || !roomId) {
 throw new Error('スクリプトプロパティに {チャットツール認証情報} / {チャットルームID} を設定してください');
 }

 const url = '(URL)' + roomId + '/messages';
 const options = {
 method: 'post',
 headers: { '{チャット認証ヘッダー}': token },
 payload: { body: message },
 muteHttpExceptions: true
 };

