function onOpen() {
 SpreadsheetApp.getUi()
 .createMenu('🔍 空き時間さがし')
 .addItem('実行する', 'findCommonFreeSlots')
 .addToUi();
}

const WD = ['日', '月', '火', '水', '木', '金', '土'];
function ymd(d) { return Utilities.formatDate(d, 'JST', 'yyyy/MM/dd') + '(' + WD[d.getDay()] + ')'; }
function md(d) { return Utilities.formatDate(d, 'JST', 'MM/dd') + '(' + WD[d.getDay()] + ')'; }
function hm(d) { return Utilities.formatDate(d, 'JST', 'HH:mm'); }

function findCommonFreeSlots() {
 const ss = SpreadsheetApp.getActiveSpreadsheet();
 const sheet = ss.getSheetByName('設定');
 if (!sheet) { Browser.msgBox('「設定」シートが見つかりません。'); return; }

 // ---------- 設定の読み込み ----------
 const trainingDateVal = sheet.getRange('B1').getValue(); // 研修日
 const durationMin = Number(sheet.getRange('B2').getValue()) || 90; // 打合せ時間(分)
 const windowDays = Number(sheet.getRange('B3').getValue()) || 7; // 前後の検索日数
 const startHour = Number(sheet.getRange('B4').getValue()) || 9; // 業務開始(時)
 const endHour = Number(sheet.getRange('B5').getValue()) || 18; // 業務終了(時)
 const includeWeekend = /はい|TRUE|含/i.test(String(sheet.getRange('B6').getValue())); // 土日を含む
 const excludeLunch = /はい|TRUE|除外/i.test(String(sheet.getRange('B7').getValue())) ||
 sheet.getRange('B7').getValue() === true; // 昼休み(12-13)除外

 if (!trainingDateVal) { Browser.msgBox('B1に研修日を入力してください。'); return; }

 // 参加者メール（A列の9行目以降。1人1行）
 const lastRow = sheet.getLastRow();
 const emails = [];
 if (lastRow >= 9) {
 sheet.getRange(9, 1, lastRow - 8, 1).getValues().forEach(function (r) {
 const e = String(r[0]).trim();
 if (e && e.indexOf('@') > -1) emails.push(e);
 });
 }
 if (emails.length === 0) { Browser.msgBox('A9以降に参加者のメールアドレスを入れてください。'); return; }

 // ---------- 検索期間（研修日の前後 windowDays 日） ----------
 const training = new Date(trainingDateVal); training.setHours(0, 0, 0, 0);
 const rangeStart = new Date(training); rangeStart.setDate(training.getDate() - windowDays); rangeStart.setHours(0, 0, 0, 0);
 const rangeEnd = new Date(training); rangeEnd.setDate(training.getDate() + windowDays); rangeEnd.setHours(23, 59, 59, 999);

 // ---------- 空き時間確認機能 で全員の予定（busy区間）をまとめて取得 ----------
 const fb = fetchBusy(emails, rangeStart, rangeEnd);
 const validEmails = emails.filter(function (e) { return fb.errors.indexOf(e) === -1; });

 // ---------- 候補スロットを30分刻みで総当たり判定 ----------
 const SLOT_STEP_MIN = 30; // 候補枠を探す間隔（分）。広めに探すならここを60や90に変更
 const now = new Date();
 const slots = [];
 for (let d = 0; d <= windowDays * 2; d++) {
 const day = new Date(rangeStart); day.setDate(rangeStart.getDate() + d);
 const dow = day.getDay();
 if (!includeWeekend && (dow === 0 || dow === 6)) continue;

 const dayStart = new Date(day); dayStart.setHours(startHour, 0, 0, 0);
 const dayEnd = new Date(day); dayEnd.setHours(endHour, 0, 0, 0); // 終業時刻

 for (let s = new Date(dayStart); s < dayEnd; s = new Date(s.getTime() + SLOT_STEP_MIN * 60000)) {
 const e = new Date(s.getTime() + durationMin * 60000);

 // 終業時刻をはみ出す枠は除外
 if (e > dayEnd) continue;
 // 昼休み(12:00-13:00)にかかる枠は除外
 if (excludeLunch) {
 const ls = new Date(day); ls.setHours(12, 0, 0, 0);
 const le = new Date(day); le.setHours(13, 0, 0, 0);
 if (s < le && e > ls) continue;
 }
 // 過去の時間帯は除外
 if (s < now) continue;

 const busyList = [];
 let freeCount = 0;
 validEmails.forEach(function (em) {
 if (isFree(fb.busy[em], s, e)) freeCount++;
 else busyList.push(em);
 });
 slots.push({ start: s, end: e, freeCount: freeCount, total: validEmails.length, busyList: busyList });
 }
 }

 // 参加できる人数が多い順 → 日時が早い順
 slots.sort(function (a, b) { return (b.freeCount - a.freeCount) || (a.start - b.start); });

 // ---------- 出力 ----------
 const out = ss.getSheetByName('空き時間') || ss.insertSheet('空き時間');
 out.clear();
 out.appendRow(['研修日', ymd(training)]);
 out.appendRow(['検索範囲', md(rangeStart) + ' 〜 ' + md(rangeEnd)]);
 out.appendRow(['参加者', validEmails.length + '名']);
 if (fb.errors.length) {
 out.appendRow(['⚠️ 予定を確認できなかった人',
 fb.errors.join(', ') + '（集計から除外しています。カレンダーの共有設定をご確認ください）']);
 }
 out.appendRow(['']);
 out.appendRow(['日付', '開始', '終了', '参加できる人数', '予定あり（参加不可）']);

 const top = slots.slice(0, 50); // 上位50件
 if (top.length === 0) {
 out.appendRow(['条件に合う候補がありませんでした。期間や時間帯を広げてください。']);
 }
 top.forEach(function (sl) {
 out.appendRow([ md(sl.start), hm(sl.start), hm(sl.end), sl.freeCount + ' / ' + sl.total, sl.busyList.join(', ') ]);
 });

 Browser.msgBox('完了しました（参加できる人数が多い順に上位' + top.length + '件を表示）。');
}

// 空き時間確認API で全員のbusy区間をまとめて取得（多人数でも高速。予定の中身は見ない）
function fetchBusy(emails, timeMin, timeMax) {
 const busy = {};
 const errors = [];
 emails.forEach(function (e) { busy[e] = []; });

 const CHUNK = 50; // 空き時間確認機能は1回あたり最大50カレンダー
 for (let i = 0; i < emails.length; i += CHUNK) {
 const chunk = emails.slice(i, i + CHUNK);
 const resp = Calendar.Freebusy.query({
 timeMin: timeMin.toISOString(),
 timeMax: timeMax.toISOString(),
 timeZone: 'Asia/Tokyo',
 items: chunk.map(function (e) { return { id: e }; })
 });
 chunk.forEach(function (e) {
 const cal = resp.calendars[e];
 if (cal && cal.busy) {
 busy[e] = cal.busy.map(function (b) { return { start: new Date(b.start), end: new Date(b.end) }; });
 }
 if (!cal || (cal.errors && cal.errors.length)) errors.push(e); // 読めなかった人
 });
 }
 return { busy: busy, errors: errors };
}

// 指定区間が busy と重ならなければ true（＝空き）
function isFree(busyList, s, e) {
 if (!busyList || busyList.length === 0) return true;
 for (let i = 0; i < busyList.length; i++) {
 if (busyList[i].start < e && busyList[i].end > s) return false;
 }
 return true;
}

