 for (let i = 1; i < data.length; i++) {
 const row = data[i];
 const advisor = String(row[COL.ADVISOR]).trim();
 const deadline = row[COL.DEADLINE];
 const contractor = String(row[COL.CONTRACTOR]).trim();
 const contractType = String(row[COL.CONTRACT_TYPE]).trim();

 if (!deadline || !advisor) continue;

 const deadlineDate = deadline instanceof Date ? deadline : new Date(deadline);
 if (isNaN(deadlineDate.getTime())) continue;

 const isTarget = CONFIG.TARGET_ADVISORS.some(
 name => normalize(advisor) === normalize(name)
 );
 if (!isTarget) continue;

 if (deadlineDate >= startDate && deadlineDate <= endDate) {
 reminders.push({
 advisor, contractor, contractType,
 deadline: deadlineDate,
 deadlineStr: Utilities.formatDate(deadlineDate, 'Asia/Tokyo', 'M/d(E)'),
 });
 }
 }

 const weekStart = Utilities.formatDate(startDate, 'Asia/Tokyo', 'M/d');
 const weekEnd = Utilities.formatDate(endDate, 'Asia/Tokyo', 'M/d');
 let message;

 if (reminders.length === 0) {
