 } else {
 message = `[info][title]📋 書類提出リマインド（${weekStart}〜${weekEnd}）[/title]`;
 message += `今週（土〜金）に提出期限の書類があります。\n期限までにCXへの提出をお願いします。\n\n`;
 for (const advisorName of CONFIG.TARGET_ADVISORS) {
 const items = reminders
 .filter(r => normalize(r.advisor) === normalize(advisorName))
 .sort((a, b) => a.deadline - b.deadline);
 if (items.length === 0) continue;
 message += `【${advisorName}】\n`;
 for (const item of items) {
 message += `・${item.contractor}\n　書類：${item.contractType}\n　期限：${item.deadlineStr}\n`;
 }
 message += '\n';
 }
 message += '[/info]';
 }

 postToChatwork(message);
}

